import type { Telemetry } from './types'
import { NoOpTelemetry } from './clients/noop-client'
import { PostHogNodeClient } from './clients/posthog-node-client'
import { PostHogBrowserClient } from './clients/posthog-browser-client'
import { JsonFileTelemetry } from './clients/json-file-client'
import { getPostHogConfig } from './config'

export const TelemetryFactory = {
    create(options?: {
        type?: 'node' | 'browser'
        attributes?: {
            sdkVersion?: string
            clientName?: 'CLI' | 'IDE' | (string & {})
            ideVersion?: string
            hostname?: string
            codingAgent?: string
        }
    }): Telemetry {
        if (process.env['NO_TELEMETRY'] === '1' || process.env['NODE_ENV'] === 'test' || !options || !options.type) {
            return new NoOpTelemetry()
        }

        const telemetryFile = process.env['FLUENT_TELEMETRY_FILE']
        if (telemetryFile) {
            return new JsonFileTelemetry(telemetryFile)
        }

        const config = getPostHogConfig()
        if (!config.apiKey) {
            return new NoOpTelemetry()
        }

        if (options.type === 'node') {
            return new PostHogNodeClient({
                apiKey: config.apiKey,
                host: config.host,
                sdkVersion: options.attributes?.sdkVersion,
                clientName: options.attributes?.clientName,
                hostname: options.attributes?.hostname,
                codingAgent: options.attributes?.codingAgent,
            })
        }

        if (options.type === 'browser') {
            return new PostHogBrowserClient({
                apiKey: config.apiKey,
                host: config.host,
                sdkVersion: options.attributes?.sdkVersion,
                clientName: options.attributes?.clientName,
                ideVersion: options.attributes?.ideVersion,
                hostname: options.attributes?.hostname,
                codingAgent: options.attributes?.codingAgent,
            })
        }

        throw new Error('Invalid telemetry type.')
    },
}
